const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  var lasVegas = ee.Geometry.Point(-115.1398, 36.1699).buffer(10000); // 10km buffer
  var startDate = '2017-06-15';
  var endDate = '2017-06-22'; // exclusive

  // 2. Data Acquisition - MODIS Terra LST (MOD11A1.061)
  var modisTerra = ee.ImageCollection('MODIS/061/MOD11A1')
    .filterDate(startDate, endDate)
    .filterBounds(lasVegas);

  var terraSize = modisTerra.size().getInfo();
  print('MODIS Terra Images:', terraSize);

  var lstCollection;
  if (terraSize === 0) {
    // Try Aqua MODIS as fallback
    var modisAqua = ee.ImageCollection('MODIS/061/MYD11A1')
      .filterDate(startDate, endDate)
      .filterBounds(lasVegas);
    var aquaSize = modisAqua.size().getInfo();
    print('MODIS Aqua Images:', aquaSize);

    if (aquaSize === 0) {
      print('No MODIS Terra or Aqua images found.');
      print('<answer>C1</answer>');
      return;
    }
    lstCollection = modisAqua;
  } else {
    lstCollection = modisTerra;
  }

  // 3. Processing: Convert LST to Fahrenheit and mask poor quality
  var convertToF = function(image) {
    var lstK = image.select('LST_Day_1km').multiply(0.02); // Scale factor for MODIS LST
    var lstC = lstK.subtract(273.15); // Kelvin to Celsius
    var lstF = lstC.multiply(9/5).add(32); // Celsius to Fahrenheit

    // Quality mask: bits 0-1 of QC_Day < 2 (good or other quality)
    var qc = image.select('QC_Day');
    var mask = qc.bitwiseAnd(3).lt(2); // 3 = binary 11

    return lstF.updateMask(mask).copyProperties(image, ['system:time_start']);
  };

  var processedCol = lstCollection.map(convertToF);

  // 4. Calculate maximum temperature over the week
  // Create a mosaic of the week by taking max pixel value
  var maxLstImage = processedCol.max();

  // Check valid pixel count
  var pixelCount = maxLstImage.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: lasVegas,
    scale: 1000,
    maxPixels: 1e9
  }).get('LST_Day_1km').getInfo();

  print('Valid pixels after masking:', pixelCount);

  if (pixelCount === 0) {
    print('No valid pixels after quality masking.');
    print('<answer>C2</answer>');
    return;
  }

  // Get maximum temperature in ROI
  var maxTemp = maxLstImage.reduceRegion({
    reducer: ee.Reducer.max(),
    geometry: lasVegas,
    scale: 1000,
    maxPixels: 1e9
  }).get('LST_Day_1km').getInfo();

  print('Maximum temperature (°F):', maxTemp);

  // 5. Validation & Final Answer
  if (maxTemp === null || maxTemp === undefined || isNaN(maxTemp)) {
    print('Calculation failed - result is NaN or null.');
    print('<answer>C3</answer>');
  } else if (maxTemp < -100 || maxTemp > 200) { // Unreasonable temperature range
    print('Temperature outside reasonable range.');
    print('<answer>C3</answer>');
  } else if (maxTemp > 130) {
    print('<answer>A</answer>');
  } else {
    print('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
